style.css:
@-moz-document domain("pinterest.com") {
body {
        background: #f1e4d6 !important;
    }

    #app {
        background: #f1e4d6 !important;
    }

    /* Top of Pinterest */
    header {
        background: #f1e4d6 !important;
    }

    /* Search bar */
    input {
        background: #dfc8b3 !important;
        color: #3b2418 !important;
    }

    input::placeholder {
        color: #765542 !important;
    }

    /* Pinterest red logo */
    svg path[fill="#E60023"] {
        fill: #4b2e20 !important;
    }

    svg path[fill="#e60023"] {
        fill: #4b2e20 !important;
    }

    svg path[fill="#BD081C"] {
        fill: #4b2e20 !important;
    }

    /* Red buttons */
    button {
        color: #4b2e20 !important;
    }

    /* Main text */
    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        color: #4b2e20 !important;
    }

    /* Links */
    a {
        color: #5a3927 !important;
    }

    /* Popups */
    [role="dialog"] {
        background: #f8f0e8 !important;
    }

    /* Menus */
    [role="menu"] {
        background: #f8f0e8 !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 9px;
    }

    ::-webkit-scrollbar-track {
        background: #e4d2c1 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: #654331 !important;
        border-radius: 10px;
    }
}
